//! Byte-for-byte parity with the Python reference implementation.
//!
//! `tests/golden/vectors.json` is generated by `screen/tools/gen_golden.py`, which runs the
//! `xbloom_ble` package (whose frames are verified against real HCI captures). CI regenerates
//! it and fails on drift, so these tests pin the Rust port to the reference.

use serde_json::Value;
use xbloom_core::crc::crc16_kermit;
use xbloom_core::protocol::{self, WirePour, WireRecipe, CANCEL_OPCODE, COMMIT_OPCODE, START_OPCODE};
use xbloom_core::recipe::{Pattern, RawRecipe, Recipe};
use xbloom_core::telemetry::parse_notification;

fn vectors() -> Value {
    serde_json::from_str(include_str!("golden/vectors.json")).expect("vectors.json parses")
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}

fn wire(v: &Value) -> WireRecipe {
    let temps = v["stage_temps"].as_array().unwrap();
    WireRecipe {
        dose: v["dose"].as_i64().unwrap() as i32,
        grind: v["grind"].as_i64().unwrap() as i32,
        stage_temps: (temps[0].as_f64().unwrap(), temps[1].as_f64().unwrap()),
        pours: v["pours"]
            .as_array()
            .unwrap()
            .iter()
            .map(|p| WirePour {
                ml: p["ml"].as_i64().unwrap() as i32,
                temp: p["temp"].as_i64().unwrap() as i32,
                pattern: Pattern::parse(p["pattern"].as_str().unwrap()),
                agitation: p["agitation"].as_bool().unwrap(),
                pause: p["pause"].as_i64().unwrap() as i32,
                rpm: p["rpm"].as_i64().unwrap() as i32,
                flow: p["flow"].as_f64().unwrap(),
            })
            .collect(),
        tail: v.get("tail").and_then(Value::as_u64).map(|t| t as u8),
        seq: v.get("seq").and_then(Value::as_u64).map_or(protocol::LOAD_SEQ, |s| s as u8),
    }
}

/// Compare JSON values treating numbers by value (15 == 15.0).
fn json_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => (x.as_f64().unwrap() - y.as_f64().unwrap()).abs() < 1e-9,
        (Value::Array(x), Value::Array(y)) => x.len() == y.len() && x.iter().zip(y).all(|(p, q)| json_eq(p, q)),
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).is_some_and(|w| json_eq(v, w)))
        }
        _ => a == b,
    }
}

#[test]
fn crc_matches_reference() {
    for case in vectors()["crc"].as_array().unwrap() {
        let data = unhex(case["data"].as_str().unwrap());
        assert_eq!(u64::from(crc16_kermit(&data)), case["crc"].as_u64().unwrap(), "crc of {}", hex(&data));
    }
}

#[test]
fn load_frames_match_reference() {
    let v = vectors();
    let proto = &v["protocol"];
    for (name, recipe) in proto["wire_recipes"].as_object().unwrap() {
        let ours: Vec<String> = protocol::build_load_frames(&wire(recipe)).unwrap().iter().map(|f| hex(f)).collect();
        let theirs: Vec<String> =
            proto["load_frames"][name].as_array().unwrap().iter().map(|f| f.as_str().unwrap().to_string()).collect();
        assert_eq!(ours, theirs, "load frames for {name}");
        // 🛑 Safety: none of them may be a brew-control opcode.
        for f in protocol::build_load_frames(&wire(recipe)).unwrap() {
            assert!(![COMMIT_OPCODE, START_OPCODE, CANCEL_OPCODE].contains(&f[3]));
        }
    }
}

#[test]
fn control_and_mode_frames_match_reference() {
    let v = vectors();
    let p = &v["protocol"];
    assert_eq!(hex(&protocol::build_commit()), p["commit"]);
    assert_eq!(hex(&protocol::build_start()), p["start"]);
    assert_eq!(hex(&protocol::build_cancel()), p["cancel"]);
    assert_eq!(hex(&protocol::build_session_start()), p["session_start"]);
    assert_eq!(hex(&protocol::build_status_query()), p["status_query"]);
    assert_eq!(hex(&protocol::build_set_mode(true)), p["set_mode_pro"]);
    assert_eq!(hex(&protocol::build_set_mode(false)), p["set_mode_auto"]);
}

#[test]
fn save_slot_frames_match_reference() {
    let v = vectors();
    let p = &v["protocol"];
    for case in p["save_slot"].as_array().unwrap() {
        let r = wire(&p["wire_recipes"][case["recipe"].as_str().unwrap()]);
        let slot = case["slot"].as_u64().unwrap() as u8;
        let frame = protocol::build_save_slot(&r, slot, case["scale"].as_bool().unwrap()).unwrap();
        assert_eq!(hex(&frame), case["frame"], "slot frame {case}");
    }
}

#[test]
fn telemetry_decodes_like_reference() {
    for case in vectors()["telemetry"].as_array().unwrap() {
        let frame = unhex(case["frame"].as_str().unwrap());
        let ours = parse_notification(&frame);
        let exp = &case["event"];
        if exp.is_null() {
            assert!(ours.is_none(), "expected no event for {}", case["frame"]);
            continue;
        }
        let ev = ours.unwrap_or_else(|| panic!("expected an event for {}", case["frame"]));
        assert_eq!(ev.state_name(), exp["state_name"].as_str().unwrap(), "name for {}", case["frame"]);
        assert_eq!(ev.state().map(|s| u64::from(s.byte())), exp["state"].as_u64(), "state for {}", case["frame"]);
        assert_eq!(ev.is_terminal(), exp["is_terminal"].as_bool().unwrap());
        for (ours, key) in [(ev.water_g, "water_g"), (ev.coffee_g, "coffee_g")] {
            match (ours, exp[key].as_f64()) {
                (None, None) => {}
                (Some(a), Some(b)) => assert!((f64::from(a) - b).abs() < 0.006, "{key}: {a} vs {b}"),
                (a, b) => panic!("{key} mismatch for {}: {a:?} vs {b:?}", case["frame"]),
            }
        }
    }
}

#[test]
fn recipes_validate_and_encode_like_reference() {
    for case in vectors()["recipes"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let parsed: Result<Recipe, String> = if let Some(y) = case.get("yaml") {
            // Example YAML files: parsed here via their JSON twin (the app crate owns YAML).
            let _ = y;
            serde_json::from_value::<RawRecipe>(case["to_dict"].clone())
                .map_err(|e| e.to_string())
                .and_then(|r| Recipe::from_raw(r).map_err(|e| e.0))
        } else {
            serde_json::from_value::<RawRecipe>(case["input"].clone())
                .map_err(|e| e.to_string())
                .and_then(|r| Recipe::from_raw(r).map_err(|e| e.0))
        };
        if case["valid"].as_bool().unwrap() {
            let r = parsed.unwrap_or_else(|e| panic!("{name} should be valid: {e}"));
            assert_eq!(i64::from(r.total_water_ml()), case["total_water_ml"].as_i64().unwrap(), "{name}");
            assert!((r.effective_ratio() - case["effective_ratio"].as_f64().unwrap()).abs() < 1e-9, "{name}");
            let frames: Vec<String> =
                protocol::build_load_frames(&r.to_wire()).unwrap().iter().map(|f| hex(f)).collect();
            let theirs: Vec<&str> =
                case["load_frames"].as_array().unwrap().iter().map(|f| f.as_str().unwrap()).collect();
            assert_eq!(frames, theirs, "{name} frames");
            let ours = serde_json::to_value(&r).unwrap();
            assert!(json_eq(&ours, &case["to_dict"]), "{name} to_dict:\n ours {ours}\n ref  {}", case["to_dict"]);
        } else {
            let err = parsed.err().unwrap_or_else(|| panic!("{name} should be invalid"));
            assert_eq!(err, case["error"].as_str().unwrap(), "{name} message");
        }
    }
}
